'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=[{id:'inbox',name:'Inbox'},{id:'ideas',name:'Ideas'},{id:'read',name:'Read later'},{id:'places',name:'Places'},{id:'inspiration',name:'Inspiration'}];
let selected=0,onlyCategory=false,showSamples=false,notes=[],toastTimer;
const samples=[{id:'s1',category:'places',type:'link',title:'Somewhere for the weekend.',body:'A little place by the water.',url:'https://example.com/',time:'Sample'},{id:'s2',category:'ideas',type:'note',title:'Keep it simple. Keep it strange.',body:'Maybe the little details are the whole idea.',time:'Sample'},{id:'s3',category:'inspiration',type:'note',title:'Green ink. Rough paper.',body:'A touch of orange. Plenty of room.',time:'Sample'}];
function data(){return [...notes,...(showSamples?samples:[])]}function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function render(){const q=$('search').value.trim().toLowerCase();const items=data().filter(x=>(!onlyCategory||x.category===categories[selected].id)&&`${x.title} ${x.body}`.toLowerCase().includes(q));$('category-filter').textContent=onlyCategory?categories[selected].name:'All chests';$('category-filter').setAttribute('aria-pressed',String(onlyCategory));$('items').innerHTML=items.length?items.map(x=>`<button class="item" type="button" data-open="${x.id}"><span class="item-type">${esc(x.type.toUpperCase())}</span><h3>${esc(x.title)}</h3>${x.body===x.title?'':`<p>${esc(x.body)}</p>`}<span class="item-meta"><span>${categories.find(c=>c.id===x.category).name}</span><span>${esc(x.time)}</span></span></button>`).join(''):`<div class="empty">${q?'Nothing by that name.':onlyCategory?'This chest is still empty.':'Your next good find goes here.'}</div>`}
const wheel=$('category-wheel'),wheelButtons=[...wheel.querySelectorAll('.wheel-item')];const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function setSelected(i){selected=Math.max(0,Math.min(categories.length-1,i));wheelButtons.forEach((b,n)=>{b.classList.toggle('selected',n===selected);b.setAttribute('aria-pressed',String(n===selected))});$('previous-category').disabled=selected===0;$('next-category').disabled=selected===categories.length-1;$('category-status').textContent='Saving to '+categories[selected].name;render()}
function selectCategory(i,smooth=true){i=Math.max(0,Math.min(categories.length-1,i));setSelected(i);wheel.scrollTo({top:i*50,behavior:smooth&&!reduced.matches?'smooth':'instant'})}
function paintWheel(){const center=wheel.scrollTop/50;wheelButtons.forEach((b,n)=>{const d=Math.max(-2,Math.min(2,n-center));b.style.transform=`perspective(350px) rotateX(${d*-24}deg) scale(${1-Math.abs(d)*.075})`;b.style.opacity=String(Math.max(.12,1-Math.abs(d)*.66))})}let settleTimer,drag=null,suppressClick=false;
wheel.addEventListener('scroll',()=>{paintWheel();const n=Math.round(wheel.scrollTop/50);if(n!==selected)setSelected(n);clearTimeout(settleTimer);if(!drag)settleTimer=setTimeout(()=>{const nearest=Math.round(wheel.scrollTop/50);if(Math.abs(wheel.scrollTop-nearest*50)>1)selectCategory(nearest)},150)},{passive:true});
wheel.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;drag={id:e.pointerId,startY:e.clientY,startScroll:wheel.scrollTop,lastY:e.clientY,lastTime:performance.now(),velocity:0,moved:false};wheel.classList.add('dragging');});
wheel.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const delta=e.clientY-drag.startY;if(Math.abs(delta)>4&&!drag.moved){drag.moved=true;wheel.setPointerCapture(e.pointerId)}if(!drag.moved)return;e.preventDefault();const now=performance.now(),dt=now-drag.lastTime;drag.velocity=dt>0?(drag.lastY-e.clientY)/dt:0;drag.lastY=e.clientY;drag.lastTime=now;wheel.scrollTop=drag.startScroll-delta});
function endDrag(e){if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;wheel.classList.remove('dragging');if(wheel.hasPointerCapture(e.pointerId))wheel.releasePointerCapture(e.pointerId);if(d.moved){suppressClick=true;const recent=performance.now()-d.lastTime<100;selectCategory(Math.round((wheel.scrollTop+(recent?Math.max(-150,Math.min(150,d.velocity*130)):0))/50));setTimeout(()=>suppressClick=false,0)}}
wheel.addEventListener('pointerup',endDrag);wheel.addEventListener('pointercancel',endDrag);wheel.addEventListener('pointerleave',e=>{if(drag&&!drag.moved)endDrag(e)});
wheel.addEventListener('click',e=>{if(suppressClick)return;const b=e.target.closest('[data-category]');if(b)selectCategory(categories.findIndex(c=>c.id===b.dataset.category))});
wheel.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?categories.length-1:selected+(e.key==='ArrowDown'?1:-1);selectCategory(n);wheelButtons[selected].focus({preventScroll:true})}});
$('previous-category').onclick=()=>selectCategory(selected-1);$('next-category').onclick=()=>selectCategory(selected+1);
$('capture-form').onsubmit=e=>{e.preventDefault();const text=$('capture').value.trim();if(!text){$('capture').focus();return}let url;try{const u=new URL(text);if(/^https?:$/.test(u.protocol)&&!/[\s]/.test(text))url=u}catch{}notes.unshift({id:'n'+Date.now(),category:categories[selected].id,type:url?'link':'note',title:url?url.hostname:text.split('\n')[0].slice(0,85),body:text,url:url?.href,time:'This session'});$('capture').value='';$('search').value='';render();toast('In '+categories[selected].name+' · this preview session only')};$('search').oninput=render;$('category-filter').onclick=()=>{onlyCategory=!onlyCategory;render()};$('scene').onclick=()=>{showSamples=!showSamples;$('scene').setAttribute('aria-pressed',String(showSamples));$('scene').textContent=showSamples?'Hide demo saves':'Demo saves';render()};$('appearance').onclick=()=>{$('appearance').textContent=document.body.classList.toggle('light')?'Morning light':'After hours'};
function detail(title,body,type,url){$('detail-title').textContent=title;$('detail-body').textContent=body;$('detail-type').textContent=type;$('detail-link').hidden=!url;if(url)$('detail-link').href=url;else $('detail-link').removeAttribute('href');$('detail').showModal()}
$('about-preview').onclick=()=>detail('A little work in progress.','Try notes and links, choose a chest, and browse recent saves. Test saves last for this session only. Uploads, OCR, recording, and encrypted sync are not implemented yet.','DESIGN PREVIEW');document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){const x=data().find(x=>x.id===b.dataset.open);detail(x.title,x.body,categories.find(c=>c.id===x.category).name,x.url)}if(b.dataset.planned)detail(b.dataset.planned,'Part of the product brief. For now, try pasting a link or writing a note.','PLANNED')});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&document.activeElement===$('capture'))$('capture-form').requestSubmit()});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_pasteinn_preview',description:'Read the selected destination and session-only notes in the Paste Inn design preview. Does not save or sync anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object');return{category:categories[selected].name,sessionOnly:true,notes:notes.map(x=>({title:x.title,body:x.body,category:x.category})),showSamples,onlyCategory}}})).catch(()=>{})}catch{}}
setSelected(0);paintWheel();
